/**
 * ER-07-07: 64-box sleep fixture (07 §5.12).
 *
 * Two islands of 32 boxes (4 wide x 2 deep x 4 high) settle on one ground
 * slab. The test measures the tick at which all 64 bodies sleep, the drift
 * over the next 600 ticks, and then wakes one body of island 0 and checks
 * that exactly that island wakes while island 1 stays asleep (RV-55).
 * Values in `recorded` are generated by this test, not invented.
 */
import { readFileSync } from "node:fs";
import { beforeAll, describe, expect, test } from "vitest";
import type { BodyHandle, ColliderHandle } from "../../src/index.js";
import {
  DT,
  bodyState,
  dynamicBox,
  ground,
  init,
  makeWorld,
  v3,
} from "../support/world.js";

interface StackFixture {
  readonly world: {
    readonly gravity: readonly number[];
    readonly fixedDt: number;
    readonly sleep: {
      readonly linearThreshold: number;
      readonly angularThreshold: number;
      readonly timeToSleep: number;
    };
  };
  readonly boxes: {
    readonly columns: number;
    readonly depth: number;
    readonly rows: number;
    readonly halfExtents: readonly number[];
    readonly gap: number;
    readonly density: number;
    readonly friction: number;
    readonly restitution: number;
    readonly islandOffsets: readonly (readonly number[])[];
    readonly ground: {
      readonly top: number;
      readonly halfExtents: readonly number[];
    };
  };
  readonly settleMaxTicks: number;
  readonly driftTicks: number;
  readonly driftLimitM: number;
  readonly wake: {
    readonly island: number;
    readonly bodyIndex: number;
    readonly impulse: readonly number[];
    readonly observationTicks: number;
    readonly settleTicksAfterWake: number;
  };
  readonly recorded: {
    readonly bodyCount: number | null;
    readonly sleepTick: number | null;
    readonly sleepingAfterSettle: number | null;
    readonly driftM: number | null;
    readonly island0AwakeAfterWake: number | null;
    readonly island1AsleepAfterWake: number | null;
    readonly settledHash: number | null;
    readonly wakeHash: number | null;
    readonly finalHash: number | null;
  };
}

const fixture = JSON.parse(
  readFileSync(new URL("../fixtures/stack-64.json", import.meta.url), "utf8"),
) as StackFixture;

interface BoxEntry {
  readonly body: BodyHandle;
  readonly collider: ColliderHandle;
}

beforeAll(async () => {
  await init();
});

describe("stack-64 fixture", () => {
  test(
    "[ER-07-07] 64 boxes sleep within 300 ticks, drift ≤ 5 mm, and waking one body wakes only its island",
    () => {
      const w = fixture.world;
      const world = makeWorld({
        gravity: v3(w.gravity[0]!, w.gravity[1]!, w.gravity[2]!),
        fixedDt: w.fixedDt,
        sleep: w.sleep,
      });
      const b = fixture.boxes;
      ground(
        world,
        b.ground.top,
        v3(
          b.ground.halfExtents[0]!,
          b.ground.halfExtents[1]!,
          b.ground.halfExtents[2]!,
        ),
        { friction: b.friction },
      );

      const hx = b.halfExtents[0]!;
      const hy = b.halfExtents[1]!;
      const hz = b.halfExtents[2]!;
      const stepX = hx * 2 + b.gap;
      const stepY = hy * 2 + b.gap;
      const stepZ = hz * 2 + b.gap;
      const islands: BoxEntry[][] = b.islandOffsets.map(() => []);
      for (let island = 0; island < b.islandOffsets.length; island += 1) {
        const offset = b.islandOffsets[island]!;
        for (let row = 0; row < b.rows; row += 1) {
          for (let depth = 0; depth < b.depth; depth += 1) {
            for (let column = 0; column < b.columns; column += 1) {
              const created = dynamicBox(
                world,
                v3(
                  offset[0]! + (column - (b.columns - 1) / 2) * stepX,
                  offset[1]! + hy + row * stepY,
                  offset[2]! + (depth - (b.depth - 1) / 2) * stepZ,
                ),
                v3(hx, hy, hz),
                {},
                {
                  density: b.density,
                  friction: b.friction,
                  restitution: b.restitution,
                },
              );
              islands[island]!.push({
                body: created.body,
                collider: created.collider,
              });
            }
          }
        }
      }
      const allBoxes = islands.flat();
      const bodyCount = world.stats.bodyCount;

      const state = bodyState();
      const countSleeping = (island: readonly BoxEntry[]): number => {
        let sleeping = 0;
        for (let i = 0; i < island.length; i += 1) {
          world.readBody(island[i]!.body, state);
          if (state.sleeping) sleeping += 1;
        }
        return sleeping;
      };

      /* Settle: the first tick after which every box reports sleeping. */
      let sleepTick = -1;
      let sleepingAfterSettle = 0;
      for (let tick = 1; tick <= fixture.settleMaxTicks; tick += 1) {
        world.step(DT);
        sleepingAfterSettle = countSleeping(allBoxes);
        if (sleepingAfterSettle === allBoxes.length) {
          sleepTick = tick;
          break;
        }
      }

      /* Drift: sleeping bodies must not move over the next 600 ticks. */
      const settledX = new Float64Array(allBoxes.length);
      const settledY = new Float64Array(allBoxes.length);
      const settledZ = new Float64Array(allBoxes.length);
      for (let i = 0; i < allBoxes.length; i += 1) {
        world.readBody(allBoxes[i]!.body, state);
        settledX[i] = state.position.x;
        settledY[i] = state.position.y;
        settledZ[i] = state.position.z;
      }
      for (let tick = 0; tick < fixture.driftTicks; tick += 1) {
        world.step(DT);
      }
      let driftM = 0;
      for (let i = 0; i < allBoxes.length; i += 1) {
        world.readBody(allBoxes[i]!.body, state);
        driftM = Math.max(
          driftM,
          Math.hypot(
            state.position.x - settledX[i]!,
            state.position.y - settledY[i]!,
            state.position.z - settledZ[i]!,
          ),
        );
      }
      const settledHash = world.stateHash();

      /* Wake one body of island 0 and observe a single tick. */
      const wakeIsland = islands[fixture.wake.island]!;
      const target = wakeIsland[fixture.wake.bodyIndex]!;
      world.applyImpulse(
        target.body,
        v3(
          fixture.wake.impulse[0]!,
          fixture.wake.impulse[1]!,
          fixture.wake.impulse[2]!,
        ),
        true,
      );
      for (let tick = 0; tick < fixture.wake.observationTicks; tick += 1) {
        world.step(DT);
      }
      const island0AwakeAfterWake =
        wakeIsland.length - countSleeping(wakeIsland);
      const other = islands[1 - fixture.wake.island]!;
      const island1AsleepAfterWake = countSleeping(other);
      const wakeHash = world.stateHash();

      for (
        let tick = 0;
        tick < fixture.wake.settleTicksAfterWake;
        tick += 1
      ) {
        world.step(DT);
      }
      const finalHash = world.stateHash();

      expect(bodyCount).toBe(65);
      expect(sleepTick).toBeGreaterThanOrEqual(0);
      expect(sleepTick).toBeLessThanOrEqual(fixture.settleMaxTicks);
      expect(sleepingAfterSettle).toBe(allBoxes.length);
      expect(driftM).toBeLessThanOrEqual(fixture.driftLimitM);
      expect(island0AwakeAfterWake).toBe(wakeIsland.length);
      expect(island1AsleepAfterWake).toBe(other.length);

      const recorded = fixture.recorded;
      if (recorded.bodyCount !== null) {
        expect(bodyCount).toBe(recorded.bodyCount);
      }
      if (recorded.sleepTick !== null) {
        expect(sleepTick).toBe(recorded.sleepTick);
      }
      if (recorded.sleepingAfterSettle !== null) {
        expect(sleepingAfterSettle).toBe(recorded.sleepingAfterSettle);
      }
      if (recorded.driftM !== null) {
        expect(driftM).toBeCloseTo(recorded.driftM, 5);
      }
      if (recorded.island0AwakeAfterWake !== null) {
        expect(island0AwakeAfterWake).toBe(recorded.island0AwakeAfterWake);
      }
      if (recorded.island1AsleepAfterWake !== null) {
        expect(island1AsleepAfterWake).toBe(recorded.island1AsleepAfterWake);
      }
      if (recorded.settledHash !== null) {
        expect(settledHash).toBe(recorded.settledHash);
      }
      if (recorded.wakeHash !== null) {
        expect(wakeHash).toBe(recorded.wakeHash);
      }
      if (recorded.finalHash !== null) {
        expect(finalHash).toBe(recorded.finalHash);
      }
      console.log(
        `[record stack-64] bodyCount=${bodyCount} sleepTick=${sleepTick} sleepingAfterSettle=${sleepingAfterSettle} driftM=${driftM} island0AwakeAfterWake=${island0AwakeAfterWake} island1AsleepAfterWake=${island1AsleepAfterWake} settledHash=${settledHash} wakeHash=${wakeHash} finalHash=${finalHash}`,
      );
      world.dispose();
    },
    120_000,
  );
});
